import{_ as a,f as n,o as l,aq as e}from"./chunks/framework.BvNt3gUw.js";const y=JSON.parse('{"title":"Pluralization","description":"","frontmatter":{},"headers":[],"relativePath":"digging-deeper/pluralization.md","filePath":"en/digging-deeper/pluralization.md","lastUpdated":1789904668000}'),o={name:"digging-deeper/pluralization.md"};function p(r,s,t,c,i,u){return l(),n("div",null,s[0]||(s[0]=[e(`<h1 id="pluralization" tabindex="-1">Pluralization <a class="header-anchor" href="#pluralization" aria-label="Permalink to “Pluralization”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Strings are important for any web application. Goravel provides simple utilities to convert words between singular and plural forms. It supports <strong>English</strong> by default, but you can add other languages or custom rules easily.</p><h2 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to “Basic Usage”">​</a></h2><p>You can use the <code>Plural</code> and <code>Singular</code> methods from the <code>pluralizer</code> package. These handle most English words automatically.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Pluralize words</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Plural</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;goose&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> // &quot;geese&quot;</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Plural</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;car&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;">   // &quot;cars&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Singularize words</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Singular</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;geese&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> // &quot;goose&quot;</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Singular</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;cars&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;">  // &quot;car&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="custom-rules" tabindex="-1">Custom Rules <a class="header-anchor" href="#custom-rules" aria-label="Permalink to “Custom Rules”">​</a></h2><p>Sometimes the default rules are not enough for specific words. Goravel lets you add your own rules to handle these cases.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Adding rules changes how pluralization works globally. You should do this when your application starts, like in the <code>Boot</code> method of a Service Provider.</p></div><h3 id="irregular-words" tabindex="-1">Irregular Words <a class="header-anchor" href="#irregular-words" aria-label="Permalink to “Irregular Words”">​</a></h3><p>If a word has a unique plural form, you can register it as an &quot;irregular&quot; word. This handles changes in both directions.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer/rules</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Register that &quot;mouse&quot; becomes &quot;mice&quot;</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterIrregular</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> rules</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">NewSubstitution</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;mouse&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;mice&quot;</span><span style="color:#68747D;">))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="uninflected-words" tabindex="-1">Uninflected Words <a class="header-anchor" href="#uninflected-words" aria-label="Permalink to “Uninflected Words”">​</a></h3><p>Some words like &quot;fish&quot; or &quot;media&quot; do not change form or are always plural. You can mark these as &quot;uninflected&quot; so the pluralizer skips them.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">// &quot;sheep&quot; stays &quot;sheep&quot; in singular and plural</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterUninflected</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;sheep&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// &quot;media&quot; is always treated as plural</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterPluralUninflected</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;media&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// &quot;data&quot; is always treated as singular</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterSingularUninflected</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;data&quot;</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="language-support" tabindex="-1">Language Support <a class="header-anchor" href="#language-support" aria-label="Permalink to “Language Support”">​</a></h2><p>Goravel uses &quot;english&quot; by default, but you can switch languages or add new ones if you need to.</p><h3 id="switching-languages" tabindex="-1">Switching Languages <a class="header-anchor" href="#switching-languages" aria-label="Permalink to “Switching Languages”">​</a></h3><p>If you have other languages registered, you can switch the active one using <code>UseLanguage</code>.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">UseLanguage</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;spanish&quot;</span><span style="color:#68747D;">);</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">    panic</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// Get the current language name</span></span>
<span class="line"><span style="color:#101820;">name </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">GetLanguage</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Name</span><span style="color:#68747D;">()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="adding-new-languages" tabindex="-1">Adding New Languages <a class="header-anchor" href="#adding-new-languages" aria-label="Permalink to “Adding New Languages”">​</a></h3><p>To add a language, you need to implement the <code>Language</code> interface. This defines how words change in that language.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/contracts/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type Language interface </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">    Name</span><span style="color:#68747D;">()</span><span style="color:#101820;"> string</span></span>
<span class="line"><span style="color:#0077B3;">    SingularRuleset</span><span style="color:#68747D;">()</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#101820;">Ruleset</span></span>
<span class="line"><span style="color:#0077B3;">    PluralRuleset</span><span style="color:#68747D;">()</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#101820;">Ruleset</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>After implementing your language struct, register it and set it as active.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">init</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#68747D;">    // Register the new language</span></span>
<span class="line"><span style="color:#101820;">    if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterLanguage</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">MyCustomLanguage</span><span style="color:#68747D;">{});</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">       panic</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">    }</span></span>
<span class="line"><span style="color:#101820;">    </span></span>
<span class="line"><span style="color:#68747D;">    // Set it as active</span></span>
<span class="line"><span style="color:#101820;">    _ </span><span style="color:#68747D;">=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">UseLanguage</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;my_custom_language&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to “Supported Languages”">​</a></h2><p>Currently, the pluralizer supports the following languages out of the box:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Language</th><th style="text-align:left;">Code</th><th style="text-align:left;">Source</th></tr></thead><tbody><tr><td style="text-align:left;">English</td><td style="text-align:left;"><code>english</code></td><td style="text-align:left;"><a href="https://github.com/goravel/framework/tree/master/support/pluralizer/english" target="_blank" rel="noreferrer">View Source</a></td></tr></tbody></table><p><em>More languages will be added in future releases. You are welcome to contribute new languages via Pull Request.</em></p>`,29)]))}const g=a(o,[["render",p]]);export{y as __pageData,g as default};
